import type { ActiveShapeProps, PieProps } from "../chart.types";

import { Pie as RechartsPie, Cell, Sector } from "recharts";
import { useTheme } from "@theme";

import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

export const RenderActiveShape = (props: ActiveShapeProps) => {
  const { showActivePieLabels } = useChart();
  const RADIAN = Math.PI / 180;
  const {
    cx,
    cy,
    midAngle = 0,
    innerRadius,
    outerRadius,
    startAngle,
    endAngle,
    fill,
    payload,
    percent,
    value,
  } = props;
  const sin = Math.sin(-RADIAN * midAngle);
  const cos = Math.cos(-RADIAN * midAngle);
  const sx = (cx as number) + (outerRadius as number) * cos;
  const sy = (cy as number) + (outerRadius as number) * sin;
  const mx = (cx as number) + ((outerRadius as number) + 8) * cos;
  const my = (cy as number) + ((outerRadius as number) + 8) * sin;
  const ex = mx + (cos >= 0 ? 1 : -1) * 22;
  const ey = my;
  const textAnchor = cos >= 0 ? "start" : "end";

  return (
    <g>
      <Sector
        cx={cx}
        cy={cy}
        endAngle={endAngle}
        fill={fill}
        innerRadius={innerRadius}
        outerRadius={outerRadius}
        startAngle={startAngle}
      />
      <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} fill="none" stroke={fill} />
      <circle cx={ex} cy={ey} fill={fill} r={2} stroke="none" />
      <text
        className={ChartClasses.pieActiveLabel}
        textAnchor={textAnchor}
        x={ex + (cos >= 0 ? 1 : -1) * 12}
        y={ey}
      >
        {payload.name}
      </text>
      <text
        className={ChartClasses.pieActiveLabel}
        dy={18}
        textAnchor={textAnchor}
        x={ex + (cos >= 0 ? 1 : -1) * 12}
        y={ey}
      >
        {showActivePieLabels === "percentage" && `${percent! * 100}%`}
        {showActivePieLabels === "value" && value}
      </text>
    </g>
  );
};

export const Pie = (props: PieProps) => {
  const { colorStartIndex = 0, data, ...rest } = props;
  const theme = useTheme();
  const { numCategoricalColors, showActivePieLabels } = useChart();

  if (!theme) {
    return <RechartsPie data={data} {...rest} />;
  }

  return (
    <RechartsPie
      data={data}
      {...rest}
      activeShape={showActivePieLabels ? RenderActiveShape : undefined}
    >
      {data?.map((_entry, index) => {
        const colorIndex = (index % numCategoricalColors) + colorStartIndex;
        const colorKey = `${colorIndex + 1}Default` as keyof typeof theme.color.data.categorical;
        const color = theme.color.data.categorical[colorKey];
        return <Cell key={`cell-${index}`} fill={color} />;
      })}
    </RechartsPie>
  );
};

Pie.displayName = "Pie";

export default Pie;
